import json
import numpy as np
import os

# Data paths
BENCHMARKS = {
    "LAMBADA": {
        "GDN": "/root/entrainment_gated_ft/lm_eval_clean/exp007/1.3b/GDN-pure/samples/lambada_openai.jsonl",
        "RetNet": "/root/entrainment_gated_ft/lm_eval_clean/exp007/1.3b/RetNet-pure/samples/lambada_openai.jsonl",
        "HGRN2": "/root/entrainment_gated_ft/lm_eval_clean/exp007/1.3b/HGRN2-pure/samples/lambada_openai.jsonl",
    },
    "HellaSwag": {
        "GDN": "/root/entrainment_gated_ft/lm_eval_clean/hellaswag/1.3B-100B-GatedDeltaNet-pure/samples/hellaswag.jsonl",
        "RetNet": "/root/entrainment_gated_ft/lm_eval_clean/hellaswag/1.3B-100B-RetNet-pure/samples/hellaswag.jsonl",
        "HGRN2": "/root/entrainment_gated_ft/lm_eval_clean/hellaswag/1.3B-100B-HGRN2-pure/samples/hellaswag.jsonl",
    },
    "ARC-Easy": {
        "GDN": "/root/entrainment_gated_ft/lm_eval_clean/arc_easy/1.3B-100B-GatedDeltaNet-pure/samples/arc_easy.jsonl",
        "RetNet": "/root/entrainment_gated_ft/lm_eval_clean/arc_easy/1.3B-100B-RetNet-pure/samples/arc_easy.jsonl",
        "HGRN2": "/root/entrainment_gated_ft/lm_eval_clean/arc_easy/1.3B-100B-HGRN2-pure/samples/arc_easy.jsonl",
    },
    "BoolQ": {
        "GDN": "/root/entrainment_gated_ft/lm_eval_clean/boolq/1.3B-100B-GatedDeltaNet-pure/samples/boolq.jsonl",
        "RetNet": "/root/entrainment_gated_ft/lm_eval_clean/boolq/1.3B-100B-RetNet-pure/samples/boolq.jsonl",
        "HGRN2": "/root/entrainment_gated_ft/lm_eval_clean/boolq/1.3B-100B-HGRN2-pure/samples/boolq.jsonl",
    },
}

def load_jsonl(path):
    samples = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line:
                samples.append(json.loads(line))
    return samples

def extract_correct_logliks(samples, benchmark):
    """Extract abs(loglik) of correct option for correctly-answered examples."""
    logliks = []
    for s in samples:
        # Check if model got it correct
        if benchmark == "LAMBADA":
            if s.get("acc", 0) != 1:
                continue
            # LAMBADA: single loglik value
            resp = s["resps"][0][0]
            if isinstance(resp, list):
                ll = float(resp[0])
            else:
                ll = float(resp)
            logliks.append(abs(ll))
        else:
            # MC tasks
            if s.get("acc", 0) != 1:
                continue
            target_idx = int(s["target"])
            resp = s["resps"][target_idx][0]
            if isinstance(resp, list):
                ll = float(resp[0])
            else:
                ll = float(resp)
            logliks.append(abs(ll))
    return logliks

def compute_stats(logliks):
    arr = np.array(logliks)
    q1, q3 = np.percentile(arr, [25, 75])
    mean_val = float(np.mean(arr))
    std_val = float(np.std(arr))
    return {
        "n_correct": len(arr),
        "mean": round(mean_val, 4),
        "std": round(std_val, 4),
        "min": round(float(np.min(arr)), 4),
        "max": round(float(np.max(arr)), 4),
        "Q1": round(float(q1), 4),
        "Q3": round(float(q3), 4),
        "IQR": round(float(q3 - q1), 4),
        "range": round(float(np.max(arr) - np.min(arr)), 4),
        "CV": round(std_val / mean_val, 4) if mean_val != 0 else None,
    }

results = {}
for bench, arch_paths in BENCHMARKS.items():
    results[bench] = {}
    for arch, path in arch_paths.items():
        if not os.path.exists(path):
            print(f"WARNING: {path} not found")
            results[bench][arch] = {"error": "file not found"}
            continue
        samples = load_jsonl(path)
        logliks = extract_correct_logliks(samples, bench)
        stats = compute_stats(logliks)
        results[bench][arch] = stats
        print(f"{bench:12s} | {arch:6s} | n={stats['n_correct']:5d} | mean={stats['mean']:.4f} | IQR={stats['IQR']:.4f} | range={stats['range']:.4f} | CV={stats['CV']:.4f}")

# Cross-benchmark summary
archs = ["GDN", "RetNet", "HGRN2"]
mean_iqr = {}
mean_range = {}
for bench in BENCHMARKS:
    iqrs = [results[bench][a]["IQR"] for a in archs if "IQR" in results[bench][a]]
    ranges = [results[bench][a]["range"] for a in archs if "range" in results[bench][a]]
    mean_iqr[bench] = round(float(np.mean(iqrs)), 4) if iqrs else None
    mean_range[bench] = round(float(np.mean(ranges)), 4) if ranges else None

# Check hypothesis: LAMBADA > HellaSwag/ARC-Easy > BoolQ
iqr_order = mean_iqr.get("LAMBADA", 0) > mean_iqr.get("HellaSwag", 0) and \
            mean_iqr.get("HellaSwag", 0) > mean_iqr.get("BoolQ", 0) and \
            mean_iqr.get("ARC-Easy", 0) > mean_iqr.get("BoolQ", 0)

range_order = mean_range.get("LAMBADA", 0) > mean_range.get("HellaSwag", 0) and \
              mean_range.get("HellaSwag", 0) > mean_range.get("BoolQ", 0) and \
              mean_range.get("ARC-Easy", 0) > mean_range.get("BoolQ", 0)

hypothesis_supported = iqr_order and range_order

output = {
    "analysis": "loglik_range_diagnostic",
    "hypothesis": "BoolQ loglik range < MC range < LAMBADA range",
    "results": results,
    "cross_benchmark_summary": {
        "mean_IQR": mean_iqr,
        "mean_range": mean_range,
        "hypothesis_supported": hypothesis_supported,
    },
}

out_path = "/tmp/loglik_range_diagnostic.json"
with open(out_path, "w") as f:
    json.dump(output, f, indent=2)

print(f"\n=== Cross-benchmark summary ===")
print(f"Mean IQR:   {mean_iqr}")
print(f"Mean Range: {mean_range}")
print(f"Hypothesis supported: {hypothesis_supported}")
print(f"\nSaved to {out_path}")
PYEOF
